(()=>{
const ptr=(obj,path)=>{if(path==null||path==='')return obj;if(path==='/')return obj[''];return String(path).split('/').slice(1).reduce((v,k)=>v==null?undefined:v[k.replace(/~1/g,'/').replace(/~0/g,'~')],obj)};
const clone=v=>v==null?v:JSON.parse(JSON.stringify(v));
const resolveBlock=(data,b)=>{const out={id:b.id,kind:b.kind};for(const [k,p] of Object.entries(b.bind||{}))out[k]=clone(ptr(data,p));return out};
const applyBudget=(block,budgets)=>{const out=clone(block);for(const [key,n] of Object.entries(budgets||{})){const [id,field]=key.split('.');if(id!==block.id||!Array.isArray(out[field]))continue;out[field]=out[field].slice(0,n)}return out};
const canonicalProfile=(data,name)=>globalThis.LRISignalVisualGrammar?.contract?.profile_aliases?.[name]||data.visual_profile_aliases?.[name]||name;
const profile=(data,name='deep_dive')=>{name=canonicalProfile(data,name);const cfg=data.visual_profiles?.[name]||{block_order:(data.visual_blocks||[]).map(x=>x.id),budgets:{}};const byId=new Map((data.visual_blocks||[]).map(b=>[b.id,b]));const blocks=(cfg.block_order||[]).map(id=>byId.get(id)).filter(Boolean).map(b=>applyBudget(resolveBlock(data,b),cfg.budgets));return {schema:data.visual_grammar?.schema||'legacy',archetype:data.visual_grammar?.archetype||data.visual_mode||'generic',name,config:cfg,blocks,byKind:Object.fromEntries(blocks.map(b=>[b.kind,b])),byId:Object.fromEntries(blocks.map(b=>[b.id,b]))}};
const materialize=(data,name='deep_dive')=>{if(!data?.visual_blocks?.length)return data;const v=profile(data,name),o={...data,__visual:v},b=v.byId;if(b.hero){o.title=b.hero.title;o.title_en=b.hero.title_en;o.subtitle=b.hero.subtitle;o.subtitle_en=b.hero.subtitle_en;o.one_line_takeaway=b.hero.takeaway}if(b.snapshot)o.snapshot={...(o.snapshot||{}),statement:b.snapshot.statement,statement_en:b.snapshot.statement_en,event_date:b.snapshot.event_date,evidence_level:b.snapshot.evidence_level,maturity:b.snapshot.maturity,metrics:b.snapshot.metrics};if(b.why)o.why_it_matters=b.why.items||[];if(b.timeline)o.timeline=b.timeline.items||[];if(b.mechanism)o.mechanism={...(o.mechanism||{}),headline:b.mechanism.headline,headline_en:b.mechanism.headline_en,nodes:b.mechanism.nodes||[]};if(b.judgments)o.supported_judgments=b.judgments.items||[];if(b.boundary)o.boundaries=b.boundary.items||[];if(b.theory)o.theory_refs=b.theory.refs||[];if(b.provenance)o.sources=b.provenance.items||[];return o};
globalThis.LRIVisualProfile={ptr,profile,resolveBlock,canonicalProfile};
globalThis.LRISignalVisual={ptr,profile,materialize,resolveBlock,canonicalProfile};
})();